const records = $input.all().map(item => item.json);

// Count interventions by follow-up category
// trim() removes unwanted spaces
const count = category =>
  records.filter(r =>
    String(r.Follow_Up_Category ?? '').trim() === category
  ).length;

// Prepare daily summary
const summary = {
  Report_Date: new Date().toISOString(),

  Total_Interventions: records.length,

  Escalation_Required: count('Escalation Required'),

  Follow_Up_Required: count('Follow-up Required'),

  Normal: count('Normal'),

  High_Priority: records.filter(r =>
    String(r.Priority ?? '').trim() === 'High'
  ).length,

  Oldest_Open_Hours: Math.max(
    0,
    ...records.map(r => Number(r.Hours_Open) || 0)
  )
};

// Email subject
summary.Email_Subject =
  `Nexus Daily Retention Monitoring | ${records.length} Interventions`;

// Email body
summary.Email_Body = `
NEXUS CUSTOMER RETENTION
DAILY MONITORING REPORT

Report Date: ${summary.Report_Date}

RETENTION SUMMARY
------------------------------
Total Interventions: ${summary.Total_Interventions}

Escalation Required: ${summary.Escalation_Required}

Follow-up Required: ${summary.Follow_Up_Required}

Normal: ${summary.Normal}

High Priority: ${summary.High_Priority}

Oldest Open Intervention: ${summary.Oldest_Open_Hours} hours


ACTION REQUIRED
------------------------------
1. Prioritise interventions requiring escalation.

2. Review customers requiring follow-up.

3. Contact high-risk customers promptly.

4. Update intervention records after action.


This report was generated automatically
by the Nexus Customer Retention System.
`;

// Return one consolidated summary
return [{ json: summary }];
